import {LightningElement,wire} from 'lwc';import {NavigationContext,navigate} from 'lightning/navigation';export default class Probe extends LightningElement {context;result='pending';@wire(NavigationContext) setContext(value){this.context=value;this.result=JSON.stringify({navigate:typeof navigate,context:typeof NavigationContext,wired:typeof value});} valid(){try{let v=navigate(this.context,{type:'standard__namedPage',attributes:{pageName:'home'}});this.result=JSON.stringify({kind:v&&typeof v.then==='function'?'promise':'sync',value:typeof v});if(v&&typeof v.then==='function')v.catch(()=>{});}catch(e){this.result=JSON.stringify({kind:'throw',name:e.name,message:e.message});}} invalid(){try{let v=navigate(this.context,null);this.result=JSON.stringify({kind:v&&typeof v.then==='function'?'promise':'sync',value:typeof v});if(v&&typeof v.then==='function')v.catch(()=>{});}catch(e){this.result=JSON.stringify({kind:'throw',name:e.name,message:e.message});}}}
